    public static event Action? LanguageChanged;

    public static void Change(string lang)
    {
        Current = lang;
        LanguageChanged?.Invoke(); // Уведомляем подписчиков
    }

    public static string T(string key)
        => _map.TryGetValue(Current, out var d) && d.TryGetValue(key, out var v) ? v : key;

}